import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int totalItems = sc.nextInt();
        int threshold = sc.nextInt();
        double[] probabilities = new double[totalItems];

        for (int i = 0; i < totalItems; i++) {
            probabilities[i] = sc.nextDouble();
        }

        double[][] comb = new double[totalItems + 1][totalItems + 1];
        double[] coeffs = new double[totalItems + 1];
        double[] totalSum = new double[1 << totalItems];
        int[] subsetSize = new int[1 << totalItems];

        comb[0][0] = 1.0;
        for (int i = 1; i <= totalItems; i++) {
            comb[i][0] = 1.0;
            for (int j = 1; j <= i; j++) {
                comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
            }
        }

        for (int mask = 0; mask < (1 << totalItems); mask++) {
            subsetSize[mask] = 0;
            totalSum[mask] = 0.0;
            for (int j = 0; j < totalItems; j++) {
                if (((mask >> j) & 1) == 1) {
                    subsetSize[mask]++;
                    totalSum[mask] += probabilities[j];
                }
            }
        }

        for (int i = threshold - 1; i >= 0; i--) {
            coeffs[i] = 1.0 - (i < coeffs.length ? coeffs[i] : 0);
            for (int j = 1; i - j >= 0; j++) {
                int index = totalItems - 1 - i + j;
                if (index >= comb.length) continue;
                coeffs[i - j] += comb[index][j] * coeffs[i];
            }
        }

        for (int i = 0; i < totalItems; i++) {
            double result = 0.0;
            if (probabilities[i] > 0.005) {
                for (int mask = 0; mask < (1 << totalItems); mask++) {
                    if (((mask >> i) & 1) == 1) continue;
                    if (subsetSize[mask] >= threshold) continue;
                    double denom = 1.0 - totalSum[mask];
                    if (denom != 0) {
                        result += coeffs[subsetSize[mask]] / denom;
                    }
                }
            }
            System.out.printf("%.12f ", probabilities[i] * result);
        }
        System.out.println();
        sc.close();
    }
}

